def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_prev, opp_prev = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    window = history[-10:] if n >= 10 else history
    w_opp_c = 0
    w_my_c = 0
    for a, b in window:
        if b == 'C':
            w_opp_c += 1
        if a == 'C':
            w_my_c += 1
    w_len = len(window)
    w_opp_d = w_len - w_opp_c
    w_my_d = w_len - w_my_c

    if n < 6:
        return 'C'

    if n >= 96:
        if opp_d <= 2:
            return 'C'
        if opp_prev == 'D' and opp_d >= 4:
            return 'D'
        if opp_prev == 'D':
            return 'C'
        if opp_d > my_d + 3:
            return 'D'
        return 'C'

    if n >= 85:
        if opp_d <= 3:
            return 'C'
        if opp_prev == 'D' and opp_d >= 6:
            return 'D'
        if opp_d * 4 > n * 3:
            return 'D'
        return 'C'

    if opp_d >= n - 1 and n >= 6:
        return 'D'

    if opp_d == 0:
        if n >= 18 and my_d == 0:
            if rng.random() < 0.6:
                return 'D'
        return 'C'

    if my_d >= 2 and opp_d <= 1 and n >= 20:
        if rng.random() < 0.25:
            return 'D'

    if w_opp_d >= w_len - 1:
        return 'D'

    if opp_prev == 'D':
        if opp_d <= 2 and my_d >= 1 and rng.random() < 0.4:
            return 'C'
        if w_opp_d <= 2:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if w_opp_d >= 5:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'D'

    if w_opp_d >= 4:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if my_d >= 2 and w_opp_d <= 1:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if opp_d * 2 >= n and n >= 10:
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'
